package com.featuredeliveryintelligence.fdi.product;import com.featuredeliveryintelligence.fdi.structural.api.CodeIntelligenceProvider;import com.featuredeliveryintelligence.fdi.structural.api.SnapshotBindingAttestor;import com.featuredeliveryintelligence.fdi.structural.api.StructuralIntelligence;import com.featuredeliveryintelligence.fdi.structural.api.StructuralMaintenance;import com.featuredeliveryintelligence.fdi.shared.RuntimeMaps;import com.featuredeliveryintelligence.fdi.shared.RuntimeContractException;import java.util.*;
public final class ProductSemantics{private ProductSemantics(){}private static final Set<String>LIFE=Set.of("DRAFT|NOT_APPLICABLE","PUBLISHED|ACTIVE","PUBLISHED|STALE","PUBLISHED|SUPERSEDED","RETIRED|NOT_APPLICABLE");public static Map<String,Object>validate(Map<String,Object>a,Collection<Map<String,Object>>existing){if(!"0.1".equals(a.get("fdi_asset_version"))||!"PRODUCT".equals(a.get("asset_family"))||!"PA-01_MINIMAL_PRODUCT_SEMANTICS".equals(a.get("asset_type")))throw new RuntimeContractException("unsupported PA-01 descriptor");for(String k:List.of("asset_id","descriptor_ref","content_ref","owner","as_of"))RuntimeMaps.requiredString(a,k);RuntimeMaps.requiredPositiveInt(a,"asset_revision");if(!LIFE.contains(a.get("publication_state")+"|"+a.get("validity_state")))throw new RuntimeContractException("illegal Product Asset lifecycle");Map<String,Object>trust=RuntimeMaps.requiredMap(a,"trust_profile");if(!trust.keySet().equals(Set.of("provenance","review","verification","authorization")))throw new RuntimeContractException("trust_profile must contain four approved facets");Map<String,Object>scope=RuntimeMaps.requiredMap(a,"scope");if(!scope.keySet().equals(Set.of("products","systems","repositories","environments"))||RuntimeMaps.list(scope,"products").isEmpty())throw new RuntimeContractException("invalid PA-01 scope");String pid=RuntimeMaps.requiredString(RuntimeMaps.requiredMap(a,"product"),"product_id");if(!RuntimeMaps.list(scope,"products").contains(pid))throw new RuntimeContractException("product_id must be included in scope.products");if("PUBLISHED".equals(a.get("publication_state"))&&"ACTIVE".equals(a.get("validity_state")))for(Map<String,Object>p:existing)if(Objects.equals(p.get("asset_id"),a.get("asset_id"))&&Objects.equals(p.get("scope"),scope)&&"PUBLISHED".equals(p.get("publication_state"))&&"ACTIVE".equals(p.get("validity_state"))&&!Objects.equals(p.get("asset_revision"),a.get("asset_revision")))throw new RuntimeContractException("one active lineage violated");return a;}public static Map<String,Object>resolveLayer1Ref(Map<String,Object>a){validate(a,List.of());if(!"PUBLISHED".equals(a.get("publication_state"))||!"ACTIVE".equals(a.get("validity_state")))throw new RuntimeContractException("resolution requires PUBLISHED + ACTIVE");Map<String,Object>r=new LinkedHashMap<>();for(String k:List.of("asset_id","asset_revision","descriptor_ref","content_ref","publication_state","validity_state","as_of","authority_dimensions","trust_profile"))r.put(k,a.get(k));r.put("scope_match",a.get("scope"));return r;}}
